from pathlib import Path
import json,hashlib,wave
import numpy as np
source=Path('outputs/Digitone-E04-PC-restored-sequencer-arp-DSP.json')
r=json.loads(source.read_text());assert r['passed'] and len(r['cases'])==3
bootfile=Path('outputs/Digitone-E04-PC-ISA-DSP-loader-startup.json')
boot=json.loads(bootfile.read_text());assert len(boot['cases'])==2 and all(c['passed'] and c['DSP_model']=='DspCpu' for c in boot['cases'])
boot['limits'][1]='Saved actual E04 loader handoff applied before the corrected raw MAIN overlay; inherited CPU/control registers and SRAM preserved. Not a corrected packaged container test.'
bootfile.write_text(json.dumps(boot,indent=2)+'\n')
original=json.loads(Path('outputs/Digitone-E04-PC-ISA-correction-summary.json').read_text())['unchanged_originals']
for file,expected in original.items():assert hashlib.sha256(Path(file).read_bytes()).hexdigest()==expected
summary={'passed':True,'PC_only':True,'firmware_modified':False,'startup_cases':2,'DSP_section_sha256':hashlib.sha256(Path('work/os144/section-7-stored.bin').read_bytes()).hexdigest(),'cases':[],'ordinary_comparison':r['ordinary_comparisons'][0],'unchanged_originals':original,'limits':r['limitations']+['DSP serial loader section 6 and FPGA internals remain emulator stand-ins.','The passing workload uses native sequencer notes; mixed live input is reported separately. No confirmed playing pattern replacement is tested.','Waveforms are model output; nonzero samples do not validate physical sound quality, cache coherence or deadlines.']}
for c in r['cases']:
 assert c['DSP_before']['model']=='DspCpu' and c['warmup']['booted'] and c['warmup']['renders']>100
 assert c['DSP_after']['booted'] and not c['DSP_after']['error'] and c['audio_nonzero_bytes']>0
 assert c['MIDI_delivery']['received']==c['MIDI_delivery']['delivered']==0
 assert c['payload_intact'] and c['ready']==1 and c['halted'] is None
 if c['mode']=='corrected':assert c['quantize'] and c['captures'] and all(q['matches'] for q in c['quantize']+c['captures'])
 file=Path('outputs/Digitone-E04-PC-restored-sequence-'+c['scenario']+'-'+c['mode']+'.wav')
 with wave.open(str(file),'rb') as w:pcm=w.readframes(w.getnframes());rate=w.getframerate()
 x=np.frombuffer(pcm,dtype='<i2').reshape(-1,2);indices=np.flatnonzero(np.any(x!=0,axis=1));assert len(indices)>0
 clip=file.with_name(file.stem+'-audible.wav')
 first=max(0,int(indices[0])-int(rate*.05));last=min(len(x),int(indices[-1])+int(rate*.1)+1)
 with wave.open(str(clip),'wb') as w:w.setnchannels(2);w.setsampwidth(2);w.setframerate(rate);w.writeframes(x[first:last].tobytes())
 item={'scenario':c['scenario'],'mode':c['mode'],'ms':c['ms'],'pitches':len(c['pitches']),'quantizer_checks':len(c['quantize']),'changed_notes':sum(q['note']!=q['actual'] for q in c['quantize']),'capture_checks':len(c['captures']),'strict_checks':c['strict_hits'],'DSP_renders':c['DSP_after']['renders'],'warmup_ms':c['warmup']['ms'],'audio_nonzero_frames':len(indices),'peak':float(np.abs(x.astype(np.int32)).max()/32768),'audio_sha256':c['audio_sha256'],'audible_clip':str(clip.resolve()),'examples':[q for q in c['quantize'] if q['note']!=q['actual']][:4]}
 summary['cases'].append(item)
assert summary['cases'][0]['changed_notes']==0
assert summary['cases'][2]['changed_notes']>0
assert summary['ordinary_comparison']['pitches_identical']
assert all(int(q['word'],16)>>31 for c in r['cases'] if c['mode']=='corrected' for q in c['quantize'])
mixed=json.loads(Path('outputs/Digitone-E04-PC-restored-arp-DSP.json').read_text())
summary['mixed_input_coverage']=[{'scenario':c['scenario'],'mode':c['mode'],'quantizer_calls':len(c['quantize']),'zero_context_calls':sum(int(q['word'],16)==0 for q in c['quantize']),'changed_notes':sum(q['note']!=q['actual'] for q in c['quantize'])} for c in mixed['cases']]
summary['live_input_context_gap_remains']=True
Path('outputs/Digitone-E04-PC-restored-arp-DSP-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# Restored-project arp eligibility and modeled audio', '', 'Both focused gaps are closed for a sequencer-only PC workload: the restored state reaches the actual arp quantizer with valid retained context, and the engine produces nonzero PCM using the unmodified section-7 DSP program. A separate mixed-input test exposes a live-MIDI context gap, described below. E04, stock recovery firmware and the corrected raw overlays are unchanged. No new flashable firmware was produced.', '', '## Causes and fixes', '', 'The previous loader-startup folders contained MAIN only. `dsplink.find_section7()` therefore found no DSP program and `install()` selected the handshake-only `DspLink`, whose documented behavior supplies no FM voices. Fresh, separate test folders now also contain unchanged stock section 7. It matches the previously extracted section-7 bytes. The engine selects `DspCpu` and executes the guest DSP program.', '', 'The previous checkpoint was `gui-raw.snap`, the first live UI frame, with DSP boot unfinished. The playback harness now waits for actual guest DSP boot and more than 100 modeled renders before configuring notes. This took six instruction-paced model seconds in each case; it is not a physical startup-time measurement and no host semaphore wakeup or DSP-ready flag is injected.', '', 'The restored sound\'s arp was OFF. Copying sequence descriptors did not establish sound arp configuration. A one-detent MODE turn also stayed inside the encoder driver\'s idle dead zone. The completed workload selects T1, opens FUNC+SYN1, and uses FUNC+NOTE (the emulator\'s KEYBOARD label) to enable the arp through the guest input dispatcher. The captured menu displays TRUE. The keyboard toggle route is documented in [Elektron\'s Digitone manual, §9.6](https://www.elektron.se/wp-content/uploads/2024/09/Digitone_User_Manual_ENG_OS1.41_231108.pdf).', '', '## Workload and results', '', 'Root 62 and raw scale 0 (or disabled scale for controls) are disclosed PC pattern-field fixtures. After warming up, native panel actions select T1, enable its arp, enter grid recording, toggle step 1, leave recording and press PLAY. No sequence descriptors are copied. No MIDI is injected into this sequencer-only test. No event fields, eligibility flags, selected-note results or private context words are seeded. Event production, selection, retained-context reads, pitch adjustment and DSP rendering execute in the guest model.', '', '| Scenario | Hooks | Pitch outputs | Oracle checks | Changed notes | Capture checks | DSP renders | Nonzero audio frames |', '|---|---|---:|---:|---:|---:|---:|---:|']
for c in summary['cases']:lines.append(f"| {c['scenario']} | {c['mode']} | {c['pitches']} | {c['quantizer_checks']} | {c['changed_notes']} | {c['capture_checks']} | {c['DSP_renders']} | {c['audio_nonzero_frames']} |")
lines+=['', 'All corrected-run context captures and quantizer returns match their independent expected values. Strict custom-instruction checks stay clean, payload bytes stay exact, readiness remains set, and there is no modeled halt or DSP error. The ordinary corrected/stock-site pitch streams match. Stock-site controls restore runtime arp hooks after the same corrected startup; they are not independent stock startup runs.', '', f"Ordinary audio bytes identical: {summary['ordinary_comparison']['audio_identical']}. Unlike the earlier zero-buffer comparison, both recordings now have nonzero audio. If the bytes differ, instruction pacing and earlier scheduling phase remain possible causes; these runs alone cannot establish which cause applies.", '', 'Corrected scale examples:']
for q in summary['cases'][2]['examples']:lines.append(f"- MIDI pitch {q['note']} → {q['actual']}; captured context {q['word']}; oracle {q['expected']}.")
lines+=['', '## Mixed-input gap', '', 'A separate run combines the native sequencer trig with a held live-MIDI chord, CC64 sustain/release and a fresh note. All 30 MIDI bytes are delivered; however, 26 of 27 quantizer calls receive context zero in each corrected run. Only the sequencer-created note retains a valid context; the enabled-scale run changes that one note and leaves the other calls unchanged. A preceding live-only run also had zero context on every quantizer call. These results establish a concrete remaining gap for this live input path; a zero-word oracle pass is not evidence of scale locking. The emitted live pitches remain stock-compatible by the helper\'s fallback behavior. It remains to trace whether context was never attached, lost on copying/selection or rejected by a later guard. The sequencer-only run has valid context on every quantizer call.', '', '## Evidence and remaining limits', '', 'Evidence: `Digitone-E04-PC-ISA-DSP-loader-startup.json`, `Digitone-E04-PC-restored-sequencer-arp-DSP.json`, `Digitone-E04-PC-restored-arp-DSP-summary.json`, the menu PNGs and paired WAV files. Clips suffixed `-audible.wav` remove the silent lead-in only. `Digitone-E04-PC-encoder-dead-zone-control.json` preserves the unsuccessful small-encoder-input control. `Digitone-E04-PC-live-MIDI-zero-context.json` and `Digitone-E04-PC-restored-arp-DSP.json` preserve live-only and mixed-input evidence.', '', 'The missing-section diagnosis is an inspection of the local engine\'s actual selection code, confirmed by real DSP renders and nonzero PCM after supplying the section. It does not diagnose the physical E04 startup freeze. Loader-derived state is still followed by a raw MAIN overlay; a corrected packaged loader test remains outstanding. DSP serial loading, FPGA behavior, timer costs and snapshot restoration remain modeled. Physical cache coherence, timing and exclusive RAM ownership are unverified. Each control restores the same guest snapshot using a disposable emulator card; evolving card contents and scheduling phase are not a complete physical stock/custom control.', '', 'Next: trace the first live note\'s zero-context path, using the successful sequencer path as a control. A separately named corrected PC-only package still needs verification through the actual loader. Keep the physical Digitone on working stock 1.44.']
Path('outputs/Digitone-E04-PC-restored-arp-audio-review.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps(summary,indent=2))
